    ('ExternalEntryStatus1Code', 'BOOK', 'Booked', 'Booked', 'Booked means that the transfer of money has been completed between account servicer and account owner. Usage: Status Booked does not necessarily imply finality of money as this depends on other factors such as the payment system used, the completion of the end-to-end transaction and the terms agreed between account servicer and owner. Status Booked is the only status that can be reversed.', 'CR0692/Maintenance2017/2018', 'registered', '2018-05-01', '2018-05-01', '', '', '', '', '', '', 'iso20022_external_code_sets_1q2026_v1'),
    ('ExternalEntryStatus1Code', 'FUTR', 'Future', 'Future', 'Entry is on the books of the account servicer and value will be applied to the account owner at a future date and time.', 'CR0692/Maintenance2017/2018', 'registered', '2018-05-01', '2018-05-01', '', '', '', '', '', '', 'iso20022_external_code_sets_1q2026_v1'),
    ('ExternalEntryStatus1Code', 'INFO', 'Information', 'Information', "Entry is only provided for information, and no booking on the account owner's account in the account servicer's ledger has been performed.", 'CR0692/Maintenance2017/2018', 'registered', '2018-05-01', '2018-05-01', '', '', '', '', '', '', 'iso20022_external_code_sets_1q2026_v1'),
    ('ExternalEntryStatus1Code', 'PDNG', 'Pending', 'Pending', "Booking on the account owner's account in the account servicer's ledger has not been completed. Usage: this can be used for expected items, or for items for which some conditions still need to be fulfilled before they can be booked. If booking takes place, the entry will be included with status Booked in subsequent account report or statement. Status Pending cannot be reversed.", 'CR0692/Maintenance2017/2018', 'registered', '2018-05-01', '2018-05-01', '', '', '', '', '', '', 'iso20022_external_code_sets_1q2026_v1'),
    ('ExternalFinancialInstrumentIdentificationType1Code', 'BELC', 'CodeSRWSecretariaatVoorRoerendeWaardenOrSVMSecrétariatDesValeursMobilières', 'Code SRW Secretariaat Voor Roerende Waarden Or SVM Secrétariat Des Valeurs Mobilières', 'National securities identification number for BE issued by the National Numbering Association SIX Telekurs Belgium.', 'ISITC/JASDEC/SWIFT CR0036', 'registered', '2010-11-30', '2010-11-30', '', '', '', '', '', '', 'iso20022_external_code_sets_1q2026_v1'),
    ('ExternalFinancialInstrumentIdentificationType1Code', 'BLOM', 'Bloomberg', 'Bloomberg', 'Ticker-like code assigned by Bloomberg to identify financial instruments.', 'ISITC/JASDEC/SWIFT CR0036', 'registered', '2010-11-30', '2010-11-30', '', '', '', '', '', '', 'iso20022_external_code_sets_1q2026_v1'),
    ('ExternalFinancialInstrumentIdentificationType1Code', 'CCCD', 'OtherNationalSecuritiesIdentificationNumber', 'Other National Securities Identification Number', 'National Securities Identification Number issued by the National Numbering Association for a country for which no specific financial instrument identification type code already yet. The first two letters of the code represents the country code (for example, EGDC for Egyptian NSIN). To be used only until the code is added to the ISO ExternalFinancialInstrumentIdentificationType1Code list.', 'ISITC/JASDEC/SWIFT CR0036', 'registered', '2010-11-30', '2010-11-30', '', '', '', '', '', '', 'iso20022_external_code_sets_1q2026_v1'),
    ('ExternalFinancialInstrumentIdentificationType1Code', 'CCDC', 'BondIdentificationCodeListChina', 'Bond Identification Code List China', 'National Bond identification number for China issued by CHINA CENTRAL DEPOSITORY & CLEARING CO., Limited.', 'CR1072/CHINA CENTRAL DEPOSITORY & CLEARING CO.,LTD.', 'registered', '2022-02-15', '2022-02-15', '', '', '', '', '', '', 'iso20022_external_code_sets_1q2026_v1'),
    ('ExternalFinancialInstrumentIdentificationType1Code', 'CMED', 'ChicagoMercantileExchangeCME', 'Chicago Mercantile Exchange CME', 'Ticker-like code assigned by the Chicago Mercantile Exchange to identify listed-derivatives instruments.', 'ISITC/JASDEC/SWIFT CR0036', 'registered', '2010-11-30', '2010-11-30', '', '', '', '', '', '', 'iso20022_external_code_sets_1q2026_v1'),
